<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Http\Requests\PurchaseRequest;use App\Models\{Product,Purchase};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;class PurchaseController extends Controller{public function index(){return response()->json(request()->user()->purchases()->with('items')->latest()->paginate(12));}public function show(Purchase $purchase){abort_unless($purchase->user_id===request()->user()->id,404);return ['data'=>$purchase->load('items')];}public function store(PurchaseRequest $r){$purchase=DB::transaction(function()use($r){$lines=[];$total='0.00';foreach($r->validated('items')as $line){$p=Product::lockForUpdate()->findOrFail($line['product_id']);if(!$p->is_active||$p->stock<$line['quantity'])abort(409,"Stock insuffisant pour {$p->name}.");$subtotal=bcmul((string)$p->price,(string)$line['quantity'],2);$total=bcadd($total,$subtotal,2);$lines[]=['product_id'=>$p->id,'product_name'=>$p->name,'unit_price'=>$p->price,'quantity'=>$line['quantity'],'subtotal'=>$subtotal];$p->decrement('stock',$line['quantity']);}$purchase=$r->user()->purchases()->create(['reference'=>'ACH-'.now()->format('Ymd').'-'.Str::upper(Str::random(6)),'status'=>'en_attente','total'=>$total,'purchased_at'=>now()]);$purchase->items()->createMany($lines);return $purchase->load('items');});return response()->json(['data'=>$purchase,'message'=>'Achat enregistré.'],201);}}
